"""A Level Chemistry (Upper Sixth): practice sets for Reaction Kinetics, Ionic Equilibria and Electrochemistry (one per lesson)."""

from .dsl import *  # noqa: F403

COURSE = ("chemistry", "upper-sixth")

KIN = "Reaction Kinetics"
ION = "Ionic Equilibria"
ELE = "Electrochemistry"


def mc(prompt, pos, right, wrongs, steps, concept, skill, hint, feedback="", **kw):
    """Four-option MC: the correct option goes at index `pos` (0-3); `wrongs` is three (text, why) pairs."""
    choices = [C(t, why=w) for t, w in wrongs]
    choices.insert(pos, C(right, correct=True))
    return MC(prompt, choices, steps, concept=concept, skill=skill, hint=hint, feedback=feedback, **kw)


